# Generated by build.py from recipe.yml for recipe http-save-a-session-as-a-har-file. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'save-har.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Fetches each URL with curl and saves the session as a HAR (HTTP Archive 1.2) file.`n# Usage: sh save-har.sh <file.har> <url>...`nhar=`$1; shift`nms() { awk `"BEGIN { printf \`"%.3f\`", (`$1) * 1000 }`"; }`npairs() {  # `"Name: value`" lines in; HAR {`"name`", `"value`"} objects out, escaped for JSON`n  tr -d '\r' | sed -e '/: /!d' -e 's/\\/\\\\/g' -e 's/`"/\\`"/g' \`n    -e 's/^\([^:]*\): \(.*\)`$/{`"name`": `"\1`", `"value`": `"\2`"}/' | paste -sd, -`n}`ncode=0`n{`n  echo '{`"log`": {`"version`": `"1.2`", `"creator`": {`"name`": `"save-har.sh`", `"version`": `"1.0`"}, `"entries`": ['`n  sep=`n  for url in `"`$@`"; do`n    started=`$(date -u +%Y-%m-%dT%H:%M:%SZ)`n    curl -s -v -D head.tmp -o body.tmp `"`$url`" 2> trace.tmp > info.tmp -w '%{method} %{http_version} %{response_code}`n%{size_download} %{time_pretransfer} %{time_starttransfer} %{time_total}`n%{content_type}' || { code=`$?; echo `"save-har.sh: curl exited `$code on `$url`" >&2; break; }`n    { read -r method version status; read -r size pre start total; read -r type; } <<EOF`n`$(tr -d '\r' < info.tmp)`nEOF`n    echo `"`$sep{\`"startedDateTime\`": \`"`$started\`", \`"time\`": `$(ms `"`$total`"),`"`n    echo `" \`"request\`": {\`"method\`": \`"`$method\`", \`"url\`": \`"`$url\`", \`"httpVersion\`": \`"HTTP/`$version\`",`"`n    echo `"  \`"headers\`": [`$(sed -n 's/^> //p' trace.tmp | pairs)],`"`n    echo `"  \`"cookies\`": [], \`"queryString\`": [], \`"headersSize\`": -1, \`"bodySize\`": 0},`"`n    echo `" \`"response\`": {\`"status\`": `$status, \`"statusText\`": \`"`$(head -n 1 head.tmp | tr -d '\r' | cut -d' ' -f3-)\`", \`"httpVersion\`": \`"HTTP/`$version\`",`"`n    echo `"  \`"headers\`": [`$(sed 1d head.tmp | pairs)],`"`n    echo `"  \`"content\`": {\`"size\`": `$size, \`"mimeType\`": \`"`$type\`", \`"encoding\`": \`"base64\`", \`"text\`": \`"`$(base64 < body.tmp | tr -d '\n')\`"},`"`n    echo `"  \`"cookies\`": [], \`"redirectURL\`": \`"\`", \`"headersSize\`": -1, \`"bodySize\`": `$size},`"`n    echo `" \`"cache\`": {}, \`"timings\`": {\`"send\`": `$(ms `"`$pre`"), \`"wait\`": `$(ms `"`$start - `$pre`"), \`"receive\`": `$(ms `"`$total - `$start`")}}`"`n    sep=,`n  done`n  echo ']}}'`n} > `"`$har.part`"`nrm -f head.tmp body.tmp trace.tmp info.tmp`nif [ `"`$code`" != 0 ]; then rm -f `"`$har.part`"; exit `"`$code`"; fi`nmv `"`$har.part`" `"`$har`"`necho `"`$# requests saved to `$har`"`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh save-har.sh session.har http://127.0.0.1:8080/hello.txt http://127.0.0.1:8080/missing.txt } finally { Stop-Process $server0 }
